package main

import "fmt"

func acquire(name string) {
	fmt.Println("open", name)
}

func release(name string) {
	fmt.Println("close", name)
}

func process() {
	opened := 0
	defer fmt.Println("opened at start:", opened)
	acquire("A")
	defer release("A")
	opened++
	acquire("B")
	defer release("B")
	opened++
	acquire("C")
	defer release("C")
	opened++
	fmt.Println("working with", opened, "resources")
}

func main() {
	process()
	fmt.Println("done")
}

