package main

import "fmt"

func show(nums []int, i int) {
	defer func() {
		if r := recover(); r != nil {
			fmt.Println("recovered:", r)
		}
	}()
	if i < 0 {
		panic("negative index")
	}
	fmt.Println(nums[i])
}

func main() {
	nums := []int{10, 20, 30}
	for {
		var i int
		if _, err := fmt.Scan(&i); err != nil {
			break
		}
		show(nums, i)
	}
	fmt.Println("done")
}

