package main

import "fmt"

func safeJob(name string, job func() int) (result int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("%s failed: %v", name, r)
		}
	}()
	return job(), nil
}

func main() {
	scores := []int{4, 6, 8}
	zero := 0
	var best *int
	jobs := []struct {
		name string
		run  func() int
	}{
		{"average", func() int {
			total := 0
			for _, s := range scores {
				total += s
			}
			return total / len(scores)
		}},
		{"split", func() int { return 12 / zero }},
		{"best", func() int { return *best }},
	}
	for _, j := range jobs {
		result, err := safeJob(j.name, j.run)
		if err != nil {
			fmt.Println("error:", err)
			continue
		}
		fmt.Printf("%s: %d\n", j.name, result)
	}
	fmt.Println("all jobs ran")
}
